enum mpg123_mode {
	MPG123_M_STEREO=0,
	MPG123_M_JOINT,
	MPG123_M_DUAL,
	MPG123_M_MONO
};

enum mpg123_flags {
	MPG123_CRC=0x1,
	MPG123_COPYRIGHT=0x2,
	MPG123_PRIVATE=0x4,
	MPG123_ORIGINAL=0x8
};

struct mpg123_frameinfo
{
	enum mpg123_version version;
	int layer;
	long rate;
	enum mpg123_mode mode;
	int mode_ext;
	int framesize;
	enum mpg123_flags flags;
	int emphasis;
	int bitrate;
	int abr_rate;
	enum mpg123_vbr vbr;
};

typedef struct 
{
	char* p;
	size_t size;
	size_t fill;
} mpg123_string;

typedef struct
{
	char lang[3];
	char id[4];
	mpg123_string description;
	mpg123_string text;
} mpg123_text;

typedef struct
{
	unsigned char version;
	mpg123_string *title;
	mpg123_string *artist;
	mpg123_string *album;
	mpg123_string *year;
	mpg123_string *genre;
	mpg123_string *comment;
	mpg123_text    *comment_list;
	size_t          comments;
	mpg123_text    *text;
	size_t          texts;
	mpg123_text    *extra;
	size_t          extras;
} mpg123_id3v2;

typedef struct
{
	char tag[3];
	char title[30];
	char artist[30];
	char album[30];
	char year[4];
	char comment[30];
	unsigned char genre;
} mpg123_id3v1;

