import random
from typing import List

# This generator produces valid text byte sequences in several encodings accepted by
# mpg123_store_utf8(enc, source, size): utf8, latin1, icy (cp1252-ish), cp1252, utf16,
# utf16 with BOM, and utf16be. The fuzzer stub chooses enc via modulo, so we only
# control the byte buffer. We embed self-identifying structures (BOMs where relevant)
# and ensure well-formed sequences to exercise conversion paths.

ENC_UTF8 = 1
ENC_LATIN1 = 2
ENC_ICY = 3
ENC_CP1252 = 4
ENC_UTF16 = 5
ENC_UTF16BOM = 6
ENC_UTF16BE = 7

# Some sample Unicode text elements covering ASCII, Latin-1, CP1252 specials, emoji, CJK
SAMPLES = [
    "",  # empty
    "Hello",  # ASCII
    "Résumé – naïve — café",  # Latin-1/CP1252 accents and dashes
    "Straße № 5 – Größe",  # German ß, №
    "¡Hola! ¿Qué tal?",  # Spanish punctuation
    "“Quotes” ‘single’ €uro £ ¥",  # CP1252 smart quotes and currency
    "日本語テキスト",  # CJK
    "🙂😂🔥",  # emoji
    "Αλφάβητο",  # Greek
    "Русский текст",  # Cyrillic
    "line1\nline2\tTabbed\\0NulInside",  # control and textual NUL marker (no actual NUL here)
]

# CP1252 0x80..0x9F printable; include a handful commonly used
CP1252_BYTES = bytes([
    0x80,  # €
    0x82,  # ‚
    0x83,  # ƒ
    0x84,  # „
    0x85,  # …
    0x86,  # †
    0x87,  # ‡
    0x88,  # ˆ
    0x89,  # ‰
    0x8A,  # Š
    0x8B,  # ‹
    0x8C,  # Œ
    0x91,  # ‘
    0x92,  # ’
    0x93,  # “
    0x94,  # ”
    0x95,  # •
    0x96,  # –
    0x97,  # —
    0x98,  # ˜
    0x99,  # ™
    0x9A,  # š
    0x9B,  # ›
    0x9C,  # œ
    0x9F,  # Ÿ
])


def pick_base_text(rng: random.Random) -> str:
    # Combine 1-3 samples randomly, possibly with separators
    parts: List[str] = []
    k = rng.randint(1, 3)
    for _ in range(k):
        s = rng.choice(SAMPLES)
        # Randomly slice a substring sometimes
        if s and rng.random() < 0.3:
            a = rng.randrange(0, len(s))
            b = rng.randrange(a, len(s))
            s = s[a:b]
        parts.append(s)
    sep_choices = [" ", " | ", "\n", " -- ", "\t"]
    sep = rng.choice(sep_choices)
    text = sep.join(parts)
    # Occasionally append CP1252-only codepoints represented as Unicode to test mapping
    if rng.random() < 0.7:
        try:
            text += " " + CP1252_BYTES.decode('cp1252')
        except Exception:
            pass
    return text


# Encoding helpers

def enc_utf8(text: str) -> bytes:
    return text.encode('utf-8')


def enc_latin1(text: str) -> bytes:
    # Ignore unencodable characters to stay valid latin1 bytes
    return text.encode('latin-1', errors='ignore')


def enc_cp1252(text: str) -> bytes:
    return text.encode('cp1252', errors='ignore')


def enc_icy(text: str, rng: random.Random) -> bytes:
    # ICY is typically cp1252 or utf-8; choose one randomly
    if rng.random() < 0.5:
        return enc_cp1252(text)
    else:
        return enc_utf8(text)


def enc_utf16(text: str, big_endian: bool, with_bom: bool) -> bytes:
    if with_bom:
        # 'utf-16' in Python emits BOM
        return text.encode('utf-16')
    else:
        if big_endian:
            return text.encode('utf-16-be')
        else:
            return text.encode('utf-16-le')


def decorate(buf: bytes, rng: random.Random) -> bytes:
    # Randomly add a trailing NUL for C-string-like scenarios
    if rng.random() < 0.5:
        buf += b"\x00"
    # Optionally wrap like ICY metadata key-value
    if rng.random() < 0.2:
        buf = b"StreamTitle='" + buf + b"';"
    # Limit to 4096
    return buf[:4096]


def build_for_encoding(enc_id: int, rng: random.Random) -> bytes:
    text = pick_base_text(rng)

    if enc_id == ENC_UTF8:
        buf = enc_utf8(text)
        # Add additional valid UTF-8 content sometimes
        if rng.random() < 0.4:
            buf += " Ångström \u030A combining".encode('utf-8', 'ignore')
        return decorate(buf, rng)

    if enc_id == ENC_LATIN1:
        buf = enc_latin1(text)
        if rng.random() < 0.3:
            buf += bytes(range(256))
        return decorate(buf, rng)

    if enc_id == ENC_ICY:
        buf = enc_icy(text, rng)
        return decorate(buf, rng)

    if enc_id == ENC_CP1252:
        buf = enc_cp1252(text)
        if rng.random() < 0.7:
            buf += CP1252_BYTES
        return decorate(buf, rng)

    if enc_id == ENC_UTF16:
        be = rng.random() < 0.5
        buf = enc_utf16(text, big_endian=be, with_bom=False)
        if rng.random() < 0.5:
            buf += b"\x00\x00"
        return decorate(buf, rng)

    if enc_id == ENC_UTF16BOM:
        buf = enc_utf16(text, big_endian=False, with_bom=True)
        if rng.random() < 0.2:
            buf += b"\xff\xfe"  # LE BOM mid-stream
        return decorate(buf, rng)

    if enc_id == ENC_UTF16BE:
        buf = enc_utf16(text, big_endian=True, with_bom=False)
        if rng.random() < 0.3:
            buf = b"\xfe\xff" + buf
        return decorate(buf, rng)

    return decorate(enc_utf8(text), rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose an encoding id in the range 1..7 (avoid 0 unknown most of the time)
    enc_choices = [ENC_UTF8, ENC_LATIN1, ENC_ICY, ENC_CP1252, ENC_UTF16, ENC_UTF16BOM, ENC_UTF16BE]
    if rng.random() < 0.1:
        # Unknown encoding path: provide sane ASCII/UTF-8 so conversion may still succeed or be handled
        buf = enc_utf8(pick_base_text(rng))
        return decorate(buf, rng)

    enc_id = rng.choice(enc_choices)
    return build_for_encoding(enc_id, rng)
